-- Aprenda se Divertindo · 121 · Trilha Policial · lote extra 21 (100 questões fáceis)
-- Rode depois do 120-trilha-policial-20.sql. Cole tudo no SQL Editor e clique em Run. Rodar de novo apenas atualiza.
-- Números 11147 a 11246: todas de nível 0 (fácil), em forma de caso prático, conferidas contra o banco.

insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id": 11147, "materia": "pen", "nivel": 0, "enunciado": "No Pelourinho, Toninho puxou o cordão de ouro do pescoço de uma turista e saiu correndo, sem ameaçá-la. Em regra, o crime é:", "opcoes": ["Furto", "Roubo", "Extorsão", "Dano"], "explicacao": "Sem violência à pessoa ou grave ameaça, a subtração é furto. Se houver violência contra a vítima, vira roubo."}, {"id": 11148, "materia": "pen", "nivel": 0, "enunciado": "Num ônibus em Feira de Santana, Duda encostou uma faca na barriga de um passageiro e levou o celular. O crime é:", "opcoes": ["Roubo", "Furto", "Dano", "Estelionato"], "explicacao": "A grave ameaça com faca caracteriza roubo (art. 157 do CP)."}, {"id": 11149, "materia": "pen", "nivel": 0, "enunciado": "Kátia foi ao banco com o cartão que achou na rua e sacou dinheiro, fingindo ser a dona. Ela comete crime contra:", "opcoes": ["O patrimônio", "A vida", "A honra", "A família"], "explicacao": "Furto mediante fraude ou estelionato, crimes contra o patrimônio."}, {"id": 11150, "materia": "pen", "nivel": 0, "enunciado": "Joel guardou na garagem uma moto que sabia ter sido roubada, para revender depois. O crime é:", "opcoes": ["Receptação", "Furto", "Roubo", "Dano"], "explicacao": "Art. 180 do CP: ocultar coisa que sabe ser produto de crime."}, {"id": 11151, "materia": "pen", "nivel": 0, "enunciado": "Numa discussão de trânsito, Marcos disse ao outro motorista: \"vou te pegar na saída e te matar\". O crime é:", "opcoes": ["Ameaça", "Injúria", "Difamação", "Lesão corporal"], "explicacao": "Art. 147 do CP."}, {"id": 11152, "materia": "pen", "nivel": 0, "enunciado": "Na fila do posto, Neide chamou o atendente de \"incompetente e ladrão de quinta\". O crime é:", "opcoes": ["Injúria", "Calúnia", "Difamação", "Ameaça"], "explicacao": "Xingamentos que ofendem a dignidade, sem fato específico, são injúria (art. 140)."}, {"id": 11153, "materia": "pen", "nivel": 0, "enunciado": "Para pagar uma dívida de jogo, Lucas sequestrou o primo e pediu dinheiro à família. O crime é:", "opcoes": ["Extorsão mediante sequestro", "Furto", "Ameaça", "Dano"], "explicacao": "Art. 159 do CP."}, {"id": 11154, "materia": "pen", "nivel": 0, "enunciado": "Bia trancou a empregada no quarto por dois dias para ela não ir embora. O crime é:", "opcoes": ["Cárcere privado", "Furto", "Injúria", "Dano"], "explicacao": "Art. 148 do CP: privar alguém da liberdade."}, {"id": 11155, "materia": "pen", "nivel": 0, "enunciado": "Na praia de Itapuã, um homem filmou mulheres trocando de roupa sem que elas soubessem e divulgou os vídeos. Isso é:", "opcoes": ["Crime", "Brincadeira permitida", "Só falta de educação", "Infração de trânsito"], "explicacao": "O registro e a divulgação não autorizados de intimidade sexual são crimes (arts. 216-B e 218-C do CP)."}, {"id": 11156, "materia": "pen", "nivel": 0, "enunciado": "Igor falsificou a assinatura do patrão num cheque para sacar dinheiro. Ele comete crime de:", "opcoes": ["Falsificação", "Ameaça", "Injúria", "Lesão corporal"], "explicacao": "Falsificação de documento, usada para obter vantagem."}, {"id": 11157, "materia": "pen", "nivel": 0, "enunciado": "Fábio deu uma rasteira na sogra só para machucá-la, e ela quebrou o braço. O crime é:", "opcoes": ["Lesão corporal", "Injúria", "Furto", "Dano"], "explicacao": "Ofender a integridade corporal de alguém é lesão corporal (art. 129)."}, {"id": 11158, "materia": "pen", "nivel": 0, "enunciado": "Sem querer, ao dar ré, Clara atropelou o filho do vizinho, que se feriu. O crime, se houver, é:", "opcoes": ["Culposo", "Doloso", "Hediondo", "Impossível"], "explicacao": "Sem intenção, mas por falta de cuidado: crime culposo."}, {"id": 11159, "materia": "pen", "nivel": 0, "enunciado": "Diante de uma faca, Wesley se defendeu com um pedaço de pau e feriu o agressor, sem exagerar. Ele agiu em:", "opcoes": ["Legítima defesa", "Estado de necessidade", "Exercício regular de direito", "Estrito cumprimento do dever"], "explicacao": "Art. 25 do CP."}, {"id": 11160, "materia": "pen", "nivel": 0, "enunciado": "Para salvar uma criança de um carro em chamas, Rui quebrou o vidro do veículo de um desconhecido. Ele agiu em:", "opcoes": ["Estado de necessidade", "Legítima defesa", "Crime de dano doloso", "Exercício arbitrário das próprias razões"], "explicacao": "Art. 24 do CP: sacrificou um bem para salvar a vida da criança."}, {"id": 11161, "materia": "pen", "nivel": 0, "enunciado": "Um cirurgião operou um paciente que autorizou a cirurgia, seguindo todas as normas médicas. O corte na pele:", "opcoes": ["Não é crime", "É lesão corporal grave", "É tentativa de homicídio", "É crime de dano"], "explicacao": "Exercício regular de direito (art. 23, III, do CP)."}, {"id": 11162, "materia": "pen", "nivel": 0, "enunciado": "Para o Código Penal, quem tem menos de 18 anos é:", "opcoes": ["Inimputável", "Imputável", "Semi-imputável", "Reincidente"], "explicacao": "Art. 27 do CP: responde pelo ECA."}, {"id": 11163, "materia": "pen", "nivel": 0, "enunciado": "Davi atirou para matar, mas a vítima foi socorrida e sobreviveu. O crime ficou:", "opcoes": ["Tentado", "Consumado", "Impossível", "Culposo"], "explicacao": "Art. 14, II, do CP."}, {"id": 11164, "materia": "pen", "nivel": 0, "enunciado": "Na rodoviária, Léo vendeu uma passagem falsa para um idoso e ficou com o dinheiro. O crime é:", "opcoes": ["Estelionato", "Roubo", "Furto", "Dano"], "explicacao": "Art. 171 do CP; contra idoso, a pena aumenta."}, {"id": 11165, "materia": "ppen", "nivel": 0, "enunciado": "Depois de ser furtada, Rose foi à delegacia contar o que aconteceu. O primeiro registro feito ali é o:", "opcoes": ["Boletim de ocorrência", "Mandado de prisão", "Alvará de soltura", "Acórdão"], "explicacao": "O BO registra o fato comunicado à polícia."}, {"id": 11166, "materia": "ppen", "nivel": 0, "enunciado": "Na Polícia Civil, a investigação de um crime é formalizada no:", "opcoes": ["Inquérito policial", "Processo eleitoral", "Contrato administrativo", "Testamento"], "explicacao": "O inquérito reúne as provas da autoria e da materialidade."}, {"id": 11167, "materia": "ppen", "nivel": 0, "enunciado": "Quem decide se o réu é culpado ou inocente, num processo comum, é o:", "opcoes": ["Juiz", "Delegado", "Escrivão", "Investigador"], "explicacao": "Nos crimes dolosos contra a vida, quem decide são os jurados."}, {"id": 11168, "materia": "ppen", "nivel": 0, "enunciado": "Preso em flagrante numa sexta, Tito foi levado ao juiz no sábado, que analisou a prisão. Essa apresentação ao juiz é a:", "opcoes": ["Audiência de custódia", "Audiência de instrução", "Sessão do júri", "Citação"], "explicacao": "Art. 310 do CPP: em até 24 horas."}, {"id": 11169, "materia": "ppen", "nivel": 0, "enunciado": "O documento assinado pelo juiz que manda prender alguém é o:", "opcoes": ["Mandado de prisão", "Boletim de ocorrência", "Termo circunstanciado", "Relatório"], "explicacao": "Art. 285 do CPP."}, {"id": 11170, "materia": "ppen", "nivel": 0, "enunciado": "O documento que manda soltar um preso é o:", "opcoes": ["Alvará de soltura", "Mandado de prisão", "Auto de flagrante", "Laudo pericial"], "explicacao": "Expedido pelo juiz."}, {"id": 11171, "materia": "ppen", "nivel": 0, "enunciado": "No processo penal, quem acusa o réu nos crimes de ação pública é o:", "opcoes": ["Promotor de justiça", "Juiz", "Delegado", "Defensor"], "explicacao": "O promotor integra o Ministério Público."}, {"id": 11172, "materia": "ppen", "nivel": 0, "enunciado": "A pessoa que sofreu o crime é chamada de:", "opcoes": ["Vítima ou ofendido", "Réu", "Querelado", "Perito"], "explicacao": "O ofendido pode ainda atuar como assistente da acusação."}, {"id": 11173, "materia": "ppen", "nivel": 0, "enunciado": "O especialista que examina vestígios e faz o laudo é o:", "opcoes": ["Perito", "Escrivão", "Jurado", "Oficial de justiça"], "explicacao": "Arts. 158 e seguintes do CPP."}, {"id": 11174, "materia": "ppen", "nivel": 0, "enunciado": "Em regra, quem está preso aguardando julgamento fica na:", "opcoes": ["Cadeia pública", "Escola pública", "Casa do juiz", "Delegacia da Mulher"], "explicacao": "Art. 102 da LEP: a cadeia pública destina-se aos presos provisórios."}, {"id": 11175, "materia": "ppen", "nivel": 0, "enunciado": "Nos crimes dolosos contra a vida, quem decide se o réu é culpado são os:", "opcoes": ["Jurados", "Delegados", "Peritos", "Advogados"], "explicacao": "Tribunal do Júri (art. 5º, XXXVIII, da Constituição)."}, {"id": 11176, "materia": "ppen", "nivel": 0, "enunciado": "Encontrado com a arma do crime logo depois do homicídio, o suspeito pode ser preso:", "opcoes": ["Em flagrante", "Só com mandado", "Só depois do júri", "Nunca"], "explicacao": "Flagrante presumido (art. 302, IV, do CPP)."}, {"id": 11177, "materia": "ppen", "nivel": 0, "enunciado": "Ao ser preso, Ari quis avisar a mãe. A Constituição garante que a prisão seja comunicada:", "opcoes": ["À família ou a quem ele indicar", "Só ao delegado-geral, nunca à família", "Só à imprensa", "A ninguém"], "explicacao": "Art. 5º, LXII, da Constituição."}, {"id": 11178, "materia": "ppen", "nivel": 0, "enunciado": "O depoimento de quem viu o crime é colhido como prova:", "opcoes": ["Testemunhal", "Pericial", "Documental", "Material"], "explicacao": "Arts. 202 e seguintes do CPP."}, {"id": 11179, "materia": "ppen", "nivel": 0, "enunciado": "Um laudo de exame de DNA é um exemplo de prova:", "opcoes": ["Pericial", "Testemunhal", "Confessional", "Indiciária apenas"], "explicacao": "Feita por perito, com conhecimento técnico."}, {"id": 11180, "materia": "leg", "nivel": 0, "enunciado": "Em Vitória da Conquista, Sônia foi espancada pelo companheiro. Para denunciar, ela pode procurar a:", "opcoes": ["Delegacia da Mulher (DEAM)", "Receita Federal", "Junta Comercial", "Capitania dos Portos da Bahia"], "explicacao": "As DEAMs atendem especialmente casos de violência contra a mulher."}, {"id": 11181, "materia": "leg", "nivel": 0, "enunciado": "Pela Lei Maria da Penha, obrigar a companheira a ter relação sexual é violência:", "opcoes": ["Sexual", "Patrimonial", "Moral", "Institucional"], "explicacao": "Art. 7º, III, da Lei 11.340/2006."}, {"id": 11182, "materia": "leg", "nivel": 0, "enunciado": "Pela Lei Maria da Penha, a mulher em situação de risco pode ser encaminhada pelo juiz a:", "opcoes": ["Programa de proteção ou casa-abrigo", "Uma cela da delegacia", "Outro estado, obrigatoriamente, sem escolha", "Um hotel pago por ela"], "explicacao": "Art. 23, I, da Lei 11.340/2006."}, {"id": 11183, "materia": "leg", "nivel": 0, "enunciado": "Mirela, de 9 anos, foi deixada sozinha em casa por dias. O órgão que zela pelos direitos dela, no município, é o:", "opcoes": ["Conselho Tutelar", "Detran", "Tribunal Eleitoral", "Cartório de Imóveis"], "explicacao": "Art. 131 do ECA."}, {"id": 11184, "materia": "leg", "nivel": 0, "enunciado": "Pelo ECA, castigo físico para educar crianças é:", "opcoes": ["Proibido", "Permitido", "Obrigatório", "Recomendado"], "explicacao": "Art. 18-A do ECA (Lei Menino Bernardo)."}, {"id": 11185, "materia": "leg", "nivel": 0, "enunciado": "Na fila do banco, Dona Lúcia, de 68 anos, tem direito a atendimento:", "opcoes": ["Prioritário", "Igual a todos", "Só depois dos jovens", "Só pela internet"], "explicacao": "Art. 3º da Lei 10.741/2003."}, {"id": 11186, "materia": "leg", "nivel": 0, "enunciado": "Seu Antônio, de 70 anos, foi impedido de entrar num ônibus municipal sem pagar. Pelo Estatuto da Pessoa Idosa, ele tem direito a:", "opcoes": ["Transporte público urbano gratuito", "Desconto de 10% só na passagem de volta", "Viajar só de pé", "Pagar o dobro"], "explicacao": "Art. 39 da Lei 10.741/2003: gratuidade para maiores de 65 anos."}, {"id": 11187, "materia": "leg", "nivel": 0, "enunciado": "Pelo Estatuto do Desarmamento, carregar arma sem autorização pela rua é:", "opcoes": ["Crime", "Permitido", "Só infração de trânsito", "Contravenção"], "explicacao": "Arts. 14 e 16 da Lei 10.826/2003."}, {"id": 11188, "materia": "leg", "nivel": 0, "enunciado": "Pela Lei de Drogas, quem vende cocaína comete:", "opcoes": ["Tráfico de drogas", "Uso pessoal", "Contravenção", "Conduta permitida"], "explicacao": "Art. 33 da Lei 11.343/2006."}, {"id": 11189, "materia": "leg", "nivel": 0, "enunciado": "Pela Lei de Drogas, o usuário pego com pequena quantidade pode receber:", "opcoes": ["Advertência e medida educativa", "Prisão de 10 anos em regime fechado", "Pena de morte", "Multa de trânsito"], "explicacao": "Art. 28 da Lei 11.343/2006."}, {"id": 11190, "materia": "leg", "nivel": 0, "enunciado": "Furar um sinal vermelho de propósito, sem causar acidente, é, pelo CTB:", "opcoes": ["Infração gravíssima", "Crime hediondo", "Conduta permitida", "Infração leve"], "explicacao": "Art. 208 do CTB."}, {"id": 11191, "materia": "leg", "nivel": 0, "enunciado": "Pelo CTB, usar o celular ao dirigir, segurando o aparelho, é:", "opcoes": ["Infração gravíssima", "Permitido", "Crime hediondo", "Infração leve"], "explicacao": "Art. 252, parágrafo único, do CTB."}, {"id": 11192, "materia": "leg", "nivel": 0, "enunciado": "Cinto de segurança, pelo CTB, é obrigatório para:", "opcoes": ["Motorista e passageiros", "Só o motorista", "Só quem senta na frente", "Ninguém em cidade"], "explicacao": "Art. 65 do CTB."}, {"id": 11193, "materia": "leg", "nivel": 0, "enunciado": "Chamar alguém de \"macaco\" por causa da cor da pele é, hoje:", "opcoes": ["Injúria racial, equiparada ao racismo", "Só uma brincadeira", "Infração de trânsito", "Contravenção leve, punida só com multa"], "explicacao": "Art. 2º-A da Lei 7.716/1989."}, {"id": 11194, "materia": "leg", "nivel": 0, "enunciado": "Policiais deram choques num preso para ele confessar. O crime é:", "opcoes": ["Tortura", "Lesão leve", "Abuso de poder simples", "Dano"], "explicacao": "Art. 1º, I, \"a\", da Lei 9.455/1997."}, {"id": 11195, "materia": "leg", "nivel": 0, "enunciado": "Estupro, latrocínio e extorsão mediante sequestro são crimes:", "opcoes": ["Hediondos", "De menor potencial ofensivo", "Culposos", "Contravenções"], "explicacao": "Art. 1º da Lei 8.072/1990."}, {"id": 11196, "materia": "leg", "nivel": 0, "enunciado": "Uma pessoa jogou lixo tóxico num rio de propósito. Pela Lei 9.605/1998, isso é:", "opcoes": ["Crime ambiental", "Conduta permitida", "Infração de trânsito", "Só falta de educação"], "explicacao": "Crime de poluição (art. 54)."}, {"id": 11197, "materia": "leg", "nivel": 0, "enunciado": "Deixar de pagar a pensão alimentícia do filho, podendo pagar, pode levar à:", "opcoes": ["Prisão civil", "Pena de morte", "Perda da nacionalidade", "Cassação do título"], "explicacao": "Art. 5º, LXVII, da Constituição: única prisão civil por dívida admitida."}, {"id": 11198, "materia": "const", "nivel": 0, "enunciado": "Pela Constituição, são símbolos da República a bandeira, o hino, as armas e o:", "opcoes": ["Selo nacional", "Brasão de Salvador", "Mapa do Brasil", "Real"], "explicacao": "Art. 13, § 1º, da Constituição."}, {"id": 11199, "materia": "const", "nivel": 0, "enunciado": "Pela Constituição, o idioma oficial do Brasil é a:", "opcoes": ["Língua portuguesa", "Língua inglesa", "Língua espanhola", "Libras apenas"], "explicacao": "Art. 13 da Constituição. A Libras é reconhecida como meio legal de comunicação."}, {"id": 11200, "materia": "const", "nivel": 0, "enunciado": "Pela Constituição, a tortura é:", "opcoes": ["Proibida", "Permitida em casos graves", "Permitida com ordem judicial", "Permitida na guerra"], "explicacao": "Art. 5º, III: ninguém será submetido a tortura."}, {"id": 11201, "materia": "const", "nivel": 0, "enunciado": "Pela Constituição, a pena de banimento, que expulsa um brasileiro do país, é:", "opcoes": ["Proibida", "Permitida para hediondos", "Permitida em tempo de paz", "Obrigatória para traidores"], "explicacao": "Art. 5º, XLVII, \"d\", da Constituição."}, {"id": 11202, "materia": "const", "nivel": 0, "enunciado": "A casa de uma pessoa, pela Constituição, é:", "opcoes": ["Asilo inviolável", "Bem público", "Propriedade do Estado", "Local sem proteção"], "explicacao": "Art. 5º, XI, da Constituição."}, {"id": 11203, "materia": "const", "nivel": 0, "enunciado": "O sigilo das cartas e das comunicações telefônicas é:", "opcoes": ["Garantido pela Constituição", "Proibido", "Sempre público, inclusive na internet", "Do governo"], "explicacao": "Art. 5º, XII. A interceptação telefônica exige ordem judicial."}, {"id": 11204, "materia": "const", "nivel": 0, "enunciado": "Para votar nas eleições, o cidadão precisa:", "opcoes": ["Estar alistado como eleitor", "Ser servidor público ou militar", "Ter carro", "Ter curso superior"], "explicacao": "Art. 14 da Constituição."}, {"id": 11205, "materia": "const", "nivel": 0, "enunciado": "Quem comanda as Forças Armadas é o:", "opcoes": ["Presidente da República", "Ministro do STF", "Governador", "Presidente do Senado Federal"], "explicacao": "Art. 84, XIII, da Constituição."}, {"id": 11206, "materia": "const", "nivel": 0, "enunciado": "O órgão máximo do Poder Judiciário brasileiro é o:", "opcoes": ["Supremo Tribunal Federal", "Superior Tribunal de Justiça", "Tribunal de Justiça", "Tribunal Regional Federal"], "explicacao": "O STF é o guardião da Constituição (art. 102)."}, {"id": 11207, "materia": "const", "nivel": 0, "enunciado": "A Assembleia Legislativa da Bahia faz parte do Poder:", "opcoes": ["Legislativo", "Executivo", "Judiciário", "Moderador"], "explicacao": "Os deputados estaduais fazem as leis estaduais."}, {"id": 11208, "materia": "const", "nivel": 0, "enunciado": "Os vereadores trabalham na:", "opcoes": ["Câmara Municipal", "Assembleia Legislativa", "Câmara dos Deputados", "Senado Federal"], "explicacao": "Fazem as leis do município."}, {"id": 11209, "materia": "const", "nivel": 0, "enunciado": "Pela Constituição, a educação é direito de todos e dever:", "opcoes": ["Do Estado e da família", "Só das escolas privadas", "Só das igrejas", "Só das empresas"], "explicacao": "Art. 205 da Constituição."}, {"id": 11210, "materia": "adm", "nivel": 0, "enunciado": "O servidor público deve tratar todos os cidadãos sem favorecer amigos. Isso é o princípio da:", "opcoes": ["Impessoalidade", "Publicidade", "Eficiência", "Continuidade"], "explicacao": "Art. 37 da Constituição."}, {"id": 11211, "materia": "adm", "nivel": 0, "enunciado": "Um servidor aceitou um carro de presente de quem tinha processo na sua repartição. Isso fere a:", "opcoes": ["Moralidade", "Publicidade", "Eficiência", "Legalidade formal"], "explicacao": "Viola a ética e a probidade administrativa."}, {"id": 11212, "materia": "adm", "nivel": 0, "enunciado": "Para entrar num cargo efetivo da Polícia Civil, em regra, é preciso:", "opcoes": ["Ser aprovado em concurso público", "Ser indicado por um político da região", "Pagar uma taxa ao governo", "Ter parentes no órgão"], "explicacao": "Art. 37, II, da Constituição."}, {"id": 11213, "materia": "adm", "nivel": 0, "enunciado": "Os prédios públicos, as viaturas e os computadores do governo são:", "opcoes": ["Bens públicos", "Bens particulares", "Bens de ninguém", "Bens dos servidores"], "explicacao": "Pertencem às pessoas jurídicas de direito público."}, {"id": 11214, "materia": "adm", "nivel": 0, "enunciado": "O servidor que pede para sair do cargo, por vontade própria, faz um pedido de:", "opcoes": ["Exoneração", "Demissão", "Aposentadoria compulsória", "Remoção"], "explicacao": "A demissão é penalidade; a exoneração pode ser a pedido."}, {"id": 11215, "materia": "adm", "nivel": 0, "enunciado": "A demissão de um servidor público é:", "opcoes": ["Uma penalidade disciplinar", "Um prêmio", "Uma promoção", "Uma licença remunerada para estudar"], "explicacao": "Aplicada após processo administrativo, com ampla defesa."}, {"id": 11216, "materia": "adm", "nivel": 0, "enunciado": "Antes de aplicar uma punição, a Administração deve garantir ao servidor:", "opcoes": ["Contraditório e ampla defesa", "Um aumento de salário antes do processo", "Férias em dobro", "Uma promoção"], "explicacao": "Art. 5º, LV, da Constituição."}, {"id": 11217, "materia": "adm", "nivel": 0, "enunciado": "Na compra de viaturas pelo governo, em regra, é obrigatório fazer:", "opcoes": ["Licitação", "Sorteio entre amigos", "Compra direta sem regras", "Doação"], "explicacao": "Art. 37, XXI, da Constituição."}, {"id": 11218, "materia": "adm", "nivel": 0, "enunciado": "Os servidores públicos estáveis podem ser demitidos sem nenhum processo?", "opcoes": ["Não", "Sim, a qualquer momento", "Sim, se o chefe quiser", "Sim, nas férias"], "explicacao": "Art. 41, § 1º, da Constituição."}, {"id": 11219, "materia": "adm", "nivel": 0, "enunciado": "O governo publicou no site oficial quanto gasta com cada contrato. Isso atende à:", "opcoes": ["Transparência e publicidade", "Sigilo absoluto dos gastos públicos", "Pessoalidade", "Ineficiência"], "explicacao": "Lei de Acesso à Informação (Lei 12.527/2011) e art. 37 da Constituição."}, {"id": 11220, "materia": "port", "nivel": 0, "enunciado": "Complete: \"As viaturas ____ no pátio da delegacia.\"", "opcoes": ["estão", "está", "estou", "estás"], "explicacao": "Sujeito plural: \"estão\"."}, {"id": 11221, "materia": "port", "nivel": 0, "enunciado": "Complete: \"O ____ foi preso em flagrante na feira.\"", "opcoes": ["suspeito", "sospeito", "suspeto", "suspeitu"], "explicacao": "A grafia correta é \"suspeito\"."}, {"id": 11222, "materia": "port", "nivel": 0, "enunciado": "Em \"O delegado chegou cedo\", o verbo é:", "opcoes": ["chegou", "delegado", "cedo", "o"], "explicacao": "O verbo indica a ação."}, {"id": 11223, "materia": "port", "nivel": 0, "enunciado": "O plural de \"policial\" é:", "opcoes": ["policiais", "policials", "policiales", "policiaes"], "explicacao": "Palavras terminadas em -al trocam o -l por -is."}, {"id": 11224, "materia": "port", "nivel": 0, "enunciado": "O antônimo de \"verdade\" é:", "opcoes": ["mentira", "certeza", "prova", "fato"], "explicacao": "Antônimo é a palavra de sentido contrário."}, {"id": 11225, "materia": "port", "nivel": 0, "enunciado": "Um sinônimo de \"suspeito\", no sentido de pessoa investigada, é:", "opcoes": ["investigado", "vítima", "jurado", "perito"], "explicacao": "Sinônimo é a palavra de sentido parecido."}, {"id": 11226, "materia": "port", "nivel": 0, "enunciado": "Assinale a frase com pontuação correta:", "opcoes": ["Onde está o suspeito?", "Onde está o suspeito.", "Onde, está o suspeito?", "Onde está, o suspeito"], "explicacao": "Pergunta direta termina com ponto de interrogação."}, {"id": 11227, "materia": "port", "nivel": 0, "enunciado": "Em \"A testemunha falou a verdade\", o sujeito é:", "opcoes": ["A testemunha", "a verdade", "falou", "verdade"], "explicacao": "Quem falou? A testemunha."}, {"id": 11228, "materia": "port", "nivel": 0, "enunciado": "A palavra \"café\" leva acento porque é:", "opcoes": ["Oxítona terminada em e", "Paroxítona", "Proparoxítona", "Monossílaba átona"], "explicacao": "Oxítonas terminadas em a, e, o (seguidas ou não de s) e em em, ens são acentuadas."}, {"id": 11229, "materia": "port", "nivel": 0, "enunciado": "Complete: \"O laudo ____ ontem pelo perito.\"", "opcoes": ["foi entregue", "foram entregues", "fomos entregues", "fui entregue"], "explicacao": "Sujeito singular \"o laudo\"."}, {"id": 11230, "materia": "inf", "nivel": 0, "enunciado": "O programa usado para escrever textos, como um relatório, é o:", "opcoes": ["Word", "Excel", "Paint", "Calculadora"], "explicacao": "Word é editor de texto; Excel é planilha."}, {"id": 11231, "materia": "inf", "nivel": 0, "enunciado": "Para fazer contas e tabelas, usa-se normalmente o:", "opcoes": ["Excel", "Word", "Bloco de Notas", "Paint"], "explicacao": "O Excel é um programa de planilhas."}, {"id": 11232, "materia": "inf", "nivel": 0, "enunciado": "Para mandar uma mensagem eletrônica com um arquivo anexo, usa-se o:", "opcoes": ["E-mail", "Paint", "Bloco de Notas", "Calculadora"], "explicacao": "O e-mail permite anexar arquivos."}, {"id": 11233, "materia": "inf", "nivel": 0, "enunciado": "Clicou num link estranho e o computador ficou lento e cheio de propagandas. Provavelmente, ele pegou um:", "opcoes": ["Malware", "Backup", "Firewall", "Driver"], "explicacao": "Malware é qualquer programa malicioso."}, {"id": 11234, "materia": "inf", "nivel": 0, "enunciado": "Para proteger o computador contra vírus, usa-se um:", "opcoes": ["Antivírus", "Editor de texto", "Navegador", "Teclado"], "explicacao": "O antivírus detecta e remove ameaças."}, {"id": 11235, "materia": "rl", "nivel": 0, "enunciado": "Uma delegacia tem 3 viaturas e cada uma leva 4 policiais. Quantos policiais cabem nas viaturas?", "opcoes": ["12", "7", "10", "14"], "explicacao": "3 × 4 = 12."}, {"id": 11236, "materia": "rl", "nivel": 0, "enunciado": "Um curso de tiro começou às 14h e durou 3 horas. Ele terminou às:", "opcoes": ["17h", "16h", "15h", "18h"], "explicacao": "14 + 3 = 17h."}, {"id": 11237, "materia": "rl", "nivel": 0, "enunciado": "Se todos os investigadores fizeram o curso e Rui é investigador, então Rui:", "opcoes": ["Fez o curso", "Não fez o curso", "É delegado", "É escrivão"], "explicacao": "Se todos fizeram, Rui também fez."}, {"id": 11238, "materia": "rl", "nivel": 0, "enunciado": "Metade de 50 é:", "opcoes": ["25", "20", "30", "10"], "explicacao": "50 ÷ 2 = 25."}, {"id": 11239, "materia": "rl", "nivel": 0, "enunciado": "Numa operação, 10 policiais se dividiram igualmente em 2 equipes. Cada equipe ficou com:", "opcoes": ["5 policiais", "2 policiais", "8 policiais", "20 policiais"], "explicacao": "10 ÷ 2 = 5."}, {"id": 11240, "materia": "dh", "nivel": 0, "enunciado": "Na delegacia, um preso pediu água e banheiro. Atender o preso com respeito é:", "opcoes": ["Dever do Estado", "Favor do policial", "Proibido por lei", "Opcional"], "explicacao": "A Constituição garante o respeito à integridade física e moral do preso."}, {"id": 11241, "materia": "dh", "nivel": 0, "enunciado": "Direitos humanos valem também para pessoas presas?", "opcoes": ["Sim", "Não", "Só para presos ricos", "Só depois da soltura"], "explicacao": "Os direitos humanos são universais."}, {"id": 11242, "materia": "dh", "nivel": 0, "enunciado": "O Disque 100 recebe denúncias de violações de direitos humanos, como violência contra:", "opcoes": ["Crianças e idosos", "Carros estacionados", "Animais de estimação apenas", "Imóveis abandonados"], "explicacao": "É o Disque Direitos Humanos."}, {"id": 11243, "materia": "dh", "nivel": 0, "enunciado": "Uma família fugiu do seu país por perseguição e chegou ao Brasil pedindo proteção. Ela é considerada:", "opcoes": ["Refugiada", "Turista", "Contrabandista", "Foragida"], "explicacao": "Lei 9.474/1997."}, {"id": 11244, "materia": "ml", "nivel": 0, "enunciado": "O IML (Instituto Médico Legal) faz, entre outros, o exame de:", "opcoes": ["Corpo de delito", "Vista para carteira", "Sangue para doação", "Raio-x de rotina"], "explicacao": "É onde se fazem perícias médicas para a Justiça."}, {"id": 11245, "materia": "ml", "nivel": 0, "enunciado": "Para identificar um corpo encontrado sem documentos, a perícia pode usar:", "opcoes": ["Digitais, arcada dentária e DNA", "Só a roupa da vítima", "Só o testemunho de vizinhos e parentes", "Só a cor do cabelo"], "explicacao": "São métodos científicos de identificação."}, {"id": 11246, "materia": "ml", "nivel": 0, "enunciado": "As marcas deixadas pelos dedos em objetos são as:", "opcoes": ["Impressões digitais", "Manchas de sangue", "Pegadas", "Fibras"], "explicacao": "Estudadas pela papiloscopia."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes where id < 1000000));
select materia, count(*) as questoes_novas from public.questoes where id between 11147 and 11246 group by materia order by 2 desc;
select public.questoes_versao() as nova_versao;
